import ui from '@zos/ui'
import { HeartRate as GaugeHeartRate, Battery as GaugeBattery } from '@zos/sensor'

const A = (p) => `images/${p}`

// ---- image arrays (frame order matters: digits 0-9, week 1-7) ----
const img_Minute_l002 = [
  A('metal-0.png'),
  A('metal-1.png'),
  A('metal-2.png'),
  A('metal-3.png'),
  A('metal-4.png'),
  A('metal-5.png'),
  A('metal-6.png'),
  A('metal-7.png'),
  A('metal-8.png'),
  A('metal-9.png'),
]

const img_Weekday_l005 = [
  A('week-mon.png'),
  A('week-tue.png'),
  A('week-wed.png'),
  A('week-thu.png'),
  A('week-fri.png'),
  A('week-sat.png'),
  A('week-sun.png'),
]

const img_Day_l006 = [
  A('day-0.png'),
  A('day-1.png'),
  A('day-2.png'),
  A('day-3.png'),
  A('day-4.png'),
  A('day-5.png'),
  A('day-6.png'),
  A('day-7.png'),
  A('day-8.png'),
  A('day-9.png'),
]

const img_Steps_progress_l007 = [
  A('step-arc-00.png'),
  A('step-arc-01.png'),
  A('step-arc-02.png'),
  A('step-arc-03.png'),
  A('step-arc-04.png'),
  A('step-arc-05.png'),
  A('step-arc-06.png'),
  A('step-arc-07.png'),
  A('step-arc-08.png'),
  A('step-arc-09.png'),
  A('step-arc-10.png'),
  A('step-arc-11.png'),
  A('step-arc-12.png'),
  A('step-arc-13.png'),
  A('step-arc-14.png'),
  A('step-arc-15.png'),
  A('step-arc-16.png'),
  A('step-arc-17.png'),
  A('step-arc-18.png'),
  A('step-arc-19.png'),
  A('step-arc-20.png'),
  A('step-arc-21.png'),
  A('step-arc-22.png'),
  A('step-arc-23.png'),
]

const img_Steps_l008 = [
  A('reading-0.png'),
  A('reading-1.png'),
  A('reading-2.png'),
  A('reading-3.png'),
  A('reading-4.png'),
  A('reading-5.png'),
  A('reading-6.png'),
  A('reading-7.png'),
  A('reading-8.png'),
  A('reading-9.png'),
]

const img_Minute_AOD_l013 = [
  A('aod-0.png'),
  A('aod-1.png'),
  A('aod-2.png'),
  A('aod-3.png'),
  A('aod-4.png'),
  A('aod-5.png'),
  A('aod-6.png'),
  A('aod-7.png'),
  A('aod-8.png'),
  A('aod-9.png'),
]

WatchFace({
  initView() {
    // px() only takes a literal number (the build replaces it, there is no px at run time); pxv() scales a computed one
    const pxv = (n) => Math.round(n * px(1000) / 1000)
    // Machined steel dial (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      w: px(390),
      h: px(450),
      src: A('steel-dial.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Minute (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(210),
      minute_startY: px(130),
      minute_zero: 1,
      minute_space: px(-3),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_l002,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Colon (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(181),
      y: px(148),
      w: px(24),
      h: px(47),
      src: A('metal-separator.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Hour (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(58),
      hour_startY: px(130),
      hour_zero: 1,
      hour_space: px(-3),
      hour_align: ui.align.LEFT,
      hour_array: img_Minute_l002,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Weekday (IMG_WEEK)
    ui.createWidget(ui.widget.IMG_WEEK, {
      x: px(137),
      y: px(76),
      week_en: img_Weekday_l005,
      week_sc: img_Weekday_l005,
      week_tc: img_Weekday_l005,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Day (IMG_DATE)
    ui.createWidget(ui.widget.IMG_DATE, {
      day_startX: px(207),
      day_startY: px(76),
      day_zero: 0,
      day_space: px(-1),
      day_align: ui.align.LEFT,
      day_follow: 0,
      day_en_array: img_Day_l006,
      day_sc_array: img_Day_l006,
      day_tc_array: img_Day_l006,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Steps progress (IMG_PROGRESS)
    ui.createWidget(ui.widget.IMG_PROGRESS, {
      x: [px(52), px(53), px(53), px(54), px(56), px(58), px(60), px(62), px(65), px(68), px(71), px(74), px(78), px(82), px(86), px(90), px(94), px(98), px(101), px(105), px(109), px(112), px(115), px(118)],
      y: [px(287), px(283), px(279), px(275), px(272), px(268), px(265), px(262), px(259), px(256), px(254), px(252), px(251), px(250), px(249), px(248), px(248), px(249), px(249), px(250), px(251), px(253), px(255), px(257)],
      image_array: img_Steps_progress_l007,
      image_length: img_Steps_progress_l007.length,
      type: ui.data_type.STEP,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Steps (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(55),
      y: px(295),
      w: px(86),
      type: ui.data_type.STEP,
      font_array: img_Steps_l008,
      h_space: px(-1),
      align_h: ui.align.CENTER_H,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Minute AOD (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(207),
      minute_startY: px(190),
      minute_zero: 1,
      minute_space: px(-2),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_AOD_l013,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Colon AOD (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(190),
      y: px(205),
      w: px(9),
      h: px(40),
      src: A('aod-separator.png'),
      show_level: ui.show_level.ONLY_AOD
    })

    // Hour AOD (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(96),
      hour_startY: px(190),
      hour_zero: 1,
      hour_space: px(-2),
      hour_align: ui.align.LEFT,
      hour_array: img_Minute_AOD_l013,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })


    // ---- user code (project.userCode) ----
    {
      const normal = ui.show_level.ONLY_NORMAL
      const digitWidth = 18
      const digitHeight = 22
      const advance = 17
      const percentWidth = 22
      const blank = A('reading-blank.png')

      function makeReading(center, top, percent) {
        const slots = Array.from({ length: 3 }, () =>
          ui.createWidget(ui.widget.IMG, {
            x: pxv(center), y: pxv(top), w: pxv(digitWidth), h: pxv(digitHeight),
            src: blank, show_level: normal,
          })
        )
        const suffix = percent ? ui.createWidget(ui.widget.IMG, {
          x: pxv(center), y: pxv(top), w: pxv(percentWidth), h: pxv(digitHeight),
          src: blank, show_level: normal,
        }) : null
        let previous
        return (value) => {
          if (previous === value) return
          const digits = value === null ? '--' : String(value)
          const showPercent = percent && value !== null
          const textWidth = digitWidth + (digits.length - 1) * advance
          const width = textWidth + (showPercent ? percentWidth : 0)
          const left = Math.round(center - width / 2)
          slots.forEach((slot, index) => {
            const char = digits[index]
            const src = char ? A(char === '-' ? 'reading-dash.png' : 'reading-' + char + '.png') : blank
            slot.setProperty(ui.prop.MORE, { x: pxv(left + index * advance), src })
          })
          if (suffix) suffix.setProperty(ui.prop.MORE, {
            x: pxv(left + textWidth - 1),
            src: showPercent ? A('reading-percent.png') : blank,
          })
          previous = value
        }
      }

      function makeRing(centerX, centerY, sweep) {
        return ui.createWidget(ui.widget.ARC_PROGRESS, {
          center_x: pxv(centerX), center_y: pxv(centerY), radius: pxv(43),
          start_angle: 0, end_angle: sweep, line_width: pxv(5),
          color: 0xff790a, level: 0, show_level: normal,
        })
      }

      function makeSensor(Sensor) {
        try { return new Sensor() } catch (error) { return null }
      }

      function readSensor(sensor, method, min, max) {
        try {
          const value = sensor[method]()
          return Number.isFinite(value) && value >= min && value <= max ? Math.round(value) : null
        } catch (error) {
          return null
        }
      }

      const heart = makeSensor(GaugeHeartRate)
      const battery = makeSensor(GaugeBattery)
      const heartRing = makeRing(195, 290, 125)
      const batteryRing = makeRing(292, 294, 98)
      const displayHeart = makeReading(195, 289, false)
      const displayBattery = makeReading(292, 295, true)

      function updateHeart() {
        const value = readSensor(heart, 'getLast', 1, 255)
        displayHeart(value)
        heartRing.setProperty(ui.prop.LEVEL, value === null ? 0 : Math.min(100, value))
      }

      function updateBattery() {
        const value = readSensor(battery, 'getCurrent', 0, 100)
        displayBattery(value)
        batteryRing.setProperty(ui.prop.LEVEL, value === null ? 0 : value)
      }

      function update() {
        updateHeart()
        updateBattery()
      }

      update()
      // Refresh when passive heart-rate data changes, and after waking the face.
      let refreshTimer = null
      function start() {
        update()
        if (refreshTimer === null) refreshTimer = setInterval(update, 15000)
      }
      function stop() {
        if (refreshTimer !== null) clearInterval(refreshTimer)
        refreshTimer = null
      }
      try { if (heart) heart.onLastChange(updateHeart) } catch (error) {}
      try { if (battery) battery.onChange(updateBattery) } catch (error) {}
      ui.createWidget(ui.widget.WIDGET_DELEGATE, { resume_call: start, pause_call: stop })
    }

    // ---- screen corners (the face switcher draws the live face square) ----
    ui.createWidget(ui.widget.IMG, { x: px(0), y: px(0), w: px(86), h: px(86), src: A('corner_tl.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
    ui.createWidget(ui.widget.IMG, { x: px(304), y: px(0), w: px(86), h: px(86), src: A('corner_tr.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
    ui.createWidget(ui.widget.IMG, { x: px(0), y: px(364), w: px(86), h: px(86), src: A('corner_bl.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
    ui.createWidget(ui.widget.IMG, { x: px(304), y: px(364), w: px(86), h: px(86), src: A('corner_br.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
  },

  build() {
    this.initView()
  },
})
